#!/usr/bin/env python3
"""Root-owned frozen qualification. Running this file measures; creating it does not."""
import datetime
import hashlib
import importlib.util
import json
import os
import pathlib
import shutil
import subprocess
import sys
import threading
import time

sys.dont_write_bytecode = True
ROOT = pathlib.Path('/var/home/zoltan/src/bit/bit-rust-client-import-adoption-completion')
TASK = pathlib.Path(__file__).resolve().parent
NODE = pathlib.Path('/var/home/zoltan/.bvm/nodejs/22.22.0/bin/node')
CLI = pathlib.Path('/var/home/zoltan/.bvm/versions/2.2.94/bit-2.2.94/node_modules/@teambit/bit/bin/bit')
WRAPPER = TASK / 'node-oracle'
REPORT_PREFIX = 'import-adoption-stack-owner'
BASELINE_PREFIX = 'import-adoption-completion'
BASELINE_EVIDENCE = TASK / 'qualification/fe37616e96c1b30f57027af1ec93345123648d66-079286f024f1'
PRIOR = TASK / 'qualification/a800673fc4da212e06b15970026ed431dec5b6ea'
STAGES = {
    'import-adoption': pathlib.Path('/var/tmp/import-adoption-file-remote-benchmark'),
    'identity': pathlib.Path('/var/tmp/identity-ci-fix-file-remote-benchmark'),
    'add': pathlib.Path('/var/tmp/add-file-remote-benchmark'),
    'fork': pathlib.Path('/var/tmp/fork-file-remote-benchmark'),
    'workspace-mutation': pathlib.Path('/var/tmp/workspace-mutation-qualified-benchmark'),
}
WORKLOADS = {
    'import-adoption': ['track-only', 'empty-directory', 'dependents', 'dependents-via', 'write-workspace-deps', 'write-package-deps'],
    'identity': ['move', 'deprecate-batch', 'rename-new', 'rename-exported', 'rename-exported-refactor'],
    'add': ['single', 'batch', 'root', 'readd', 'ignored', 'link-failure'],
    'fork': ['local-single', 'local-refactor', 'local-batch', 'remote-single', 'remote-batch', 'scope-batch'],
    'workspace-mutation': ['remove-tagged-batch', 'delete-tagged-batch', 'recover-deleted-batch', 'scope-rename-mixed'],
}


def sha(path):
    return hashlib.sha256(pathlib.Path(path).read_bytes()).hexdigest()


def atomic(path, value):
    temporary = path.with_name(path.name + '.tmp')
    temporary.write_text(json.dumps(value, indent=2) + '\n')
    temporary.replace(path)


def git(*args):
    return subprocess.check_output(['git', *args], cwd=ROOT, text=True).strip()


def load_common():
    spec = importlib.util.spec_from_file_location('qualification_common', ROOT / 'scripts/rust/bench-stash.py')
    common = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(common)
    return common


def fingerprint(root):
    # Byte-identical preparation algorithm: includes root, empty dirs, modes and symlinks.
    root = pathlib.Path(root)
    digest = hashlib.sha256()
    for path in [root, *sorted(root.rglob('*'))]:
        metadata = path.lstat()
        record = [str(path.relative_to(root)), metadata.st_mode]
        if path.is_symlink():
            record += ['symlink', os.readlink(path)]
        elif path.is_dir():
            record += ['directory']
        elif path.is_file():
            record += ['file', metadata.st_size, sha(path)]
        else:
            raise RuntimeError(f'unsupported fixture entry: {path}')
        digest.update(json.dumps(record, separators=(',', ':')).encode() + b'\n')
    return digest.hexdigest()


def prior_failed():
    original = TASK / 'import-controller.py'
    receipt = json.loads((PRIOR / 'resume.json').read_text())
    if sha(original) != receipt['identity']['controller_sha256']:
        raise RuntimeError('historical failed controller source changed')
    if len(receipt['attempts']) != 1:
        raise RuntimeError('historical failed attempt set changed')
    attempt = receipt['attempts'][0]
    if attempt['exit_code'] != 1 or attempt['performance_valid'] is not False:
        raise RuntimeError('prior failed attempt must remain failed and unqualified')
    files = {str(path.relative_to(PRIOR)): sha(path) for path in sorted(PRIOR.rglob('*')) if path.is_file()}
    for name, digest in attempt['files'].items():
        if files.get(name) != digest:
            raise RuntimeError('prior failed raw evidence changed')
    return {'path': str(PRIOR), 'files': files, 'controller_path': str(original),
            'controller_sha256': sha(original), 'status': 'FAILED/unqualified; no timing reuse',
            'review': 'Original strict snapshot-group comparison failed on scope-rename-mixed/timed/0; '
                      'Node and Rust crossed second-resolution backup boundaries differently. '
                      'Closed monitor peak88.25percent also invalidated host timing. '
                      'This failure is preserved, not retagged under the new oracle method.'}


def prior_archive(prior):
    resume_record = json.loads((PRIOR / 'resume.json').read_text())
    result = dict(prior, controller_source=pathlib.Path(prior['controller_path']).read_text(),
                  resume=resume_record, monitors={}, command_output={})
    for path in sorted(PRIOR.glob('*.monitor.json')):
        result['monitors'][path.name] = json.loads(path.read_text())
    for path in sorted(PRIOR.iterdir()):
        if path.suffix in ['.stdout', '.stderr']:
            result['command_output'][path.name] = path.read_text()
    result['result_files'] = {path.name: {'sha256': sha(path), 'data': json.loads(path.read_text())}
                              for path in sorted(PRIOR.glob('*.result.json'))}
    result['result_note'] = 'The failed helper did not emit a complete result report; raw state evidence remains hashed and retained.'
    return result


def baseline_identity():
    paths = [ROOT / 'scripts/rust/benchmarks' / (BASELINE_PREFIX + suffix + '.json')
             for suffix in ['', '-qualification', '-fork', '-identity', '-add', '-mutation', '-regressions']]
    summary = BASELINE_EVIDENCE / 'summary.json'
    data = json.loads(summary.read_text())
    if data != {'pairs': 450, 'native_pairs': 440, 'eligible_modes': 88, 'slower': []}:
        raise RuntimeError('preserved completed baseline summary changed')
    old_controller = TASK / 'import-oracle-controller.py'
    record = json.loads((BASELINE_EVIDENCE / 'resume.json').read_text())
    if sha(old_controller) != record['identity']['controller_sha256']:
        raise RuntimeError('completed baseline controller changed')
    preserved = [TASK / name for name in ['baseline-artifact.json', 'baseline-functional.json', 'baseline-build.py']]
    return {'reports': {str(path): sha(path) for path in paths},
            'preserved_build_inputs': {str(path): sha(path) for path in preserved},
            'summary': {'path': str(summary), 'sha256': sha(summary), 'data': data},
            'evidence': str(BASELINE_EVIDENCE),
            'resume_sha256': sha(BASELINE_EVIDENCE / 'resume.json'),
            'controller': {'path': str(old_controller), 'sha256': sha(old_controller)},
            'note': 'Complete original450-pair qualification remains unchanged and valid for its original production source. No baseline measurements qualify the changed stack-owner source.'}


def baseline_archive(baseline):
    records = {}
    for name, digest in baseline['reports'].items():
        row = {'path': name, 'sha256': digest}
        if not name.endswith('-qualification.json'):
            row['data'] = json.loads(pathlib.Path(name).read_text())
        else:
            row['note'] = 'Original full qualification includes raw proofs; referenced with exact SHA rather than duplicating the14MB archive.'
        records[name] = row
    return dict(baseline, reports=records)


def frozen_inputs(common, artifact):
    # The preparer supplies immutable baselines only; no measured runtime/evidence dirs.
    preparation_path = TASK / 'fixture-manifest.json'
    preparation = json.loads(preparation_path.read_text())
    immutable = {}
    for stage in preparation['stages'].values():
        for name, digest in stage['immutable_fingerprints'].items():
            if name in immutable and immutable[name] != digest:
                raise RuntimeError('contradictory fixture baselines')
            immutable[name] = digest
    actual_fixtures = {name: fingerprint(name) for name in immutable}
    if not immutable or actual_fixtures != immutable:
        raise RuntimeError('immutable fixtures differ from completed preparation')
    original_artifact = preparation['recipe']['artifact']
    baseline = baseline_identity()
    original_report = json.loads((ROOT / 'scripts/rust/benchmarks/import-adoption-completion.json').read_text())
    if original_artifact != original_report['build_provenance']:
        raise RuntimeError('reused fixtures differ from original qualified artifact provenance')
    if sha(original_artifact['artifact']) != original_artifact['binary_sha256']:
        raise RuntimeError('preserved original artifact changed')
    if preparation['recipe']['node_sha256'] != sha(NODE) or preparation['recipe']['node_cli_sha256'] != sha(CLI):
        raise RuntimeError('reused fixtures require the original exact pinned Node/CLI')

    supplemental = preparation.get('supplemental_oracles', {}).get('scope_bitmap_history')
    oracle_path = STAGES['workspace-mutation'] / 'scope-bitmap-history-oracle.json'
    if not supplemental or supplemental.get('path') != str(oracle_path) or supplemental.get('sha256') != sha(oracle_path):
        raise RuntimeError('completed preparation must bind supplemental history-oracle provenance')
    functional_path = TASK / 'functional.json'
    functional = json.loads(functional_path.read_text())
    if {check['check'] for check in functional['checks']} != {'fmt','clippy','dylint','doc','workspace','e2e','port-plan','scope'} or any(check['code'] != 0 for check in functional['checks']):
        raise RuntimeError('all seven current-tree checks must pass before launch')
    if functional.get('python_unit_validation', {}).get('passed') is not True or functional['python_unit_validation'].get('tests') != 17:
        raise RuntimeError('current-tree Python helper unit validation must pass before launch')
    units = functional['python_unit_validation']
    if sha(units['log']) != units['log_sha256']:
        raise RuntimeError('Python unit validation log changed')
    for name, digest in units['helper_sha256'].items():
        if sha(ROOT / 'scripts/rust' / name) != digest:
            raise RuntimeError('Python unit helper changed after validation')
    stack = functional.get('stack_validation', {})
    if stack.get('code') != 0 or stack.get('cases') != 4 or stack.get('native_source') != common.native_source(ROOT):
        raise RuntimeError('four-case current-source reduced-stack validation required')
    if sha(stack['log']) != stack['log_sha256']:
        raise RuntimeError('reduced-stack validation log changed')
    correction_path = TASK / 'baseline-provenance-correction.json'
    correction = json.loads(correction_path.read_text())
    if correction['binary_sha256'] != original_artifact['binary_sha256']:
        raise RuntimeError('baseline compiler correction names another binary')
    if not artifact['rustc'].startswith('rustc 1.97.'):
        raise RuntimeError('new artifact must record the actual pinned native rustc1.97 builder')
    inputs = {
        'native_source': common.native_source(ROOT),
        'head': git('rev-parse', 'HEAD'),
        'source_tree': git('rev-parse', 'HEAD^{tree}'),
        'artifact_manifest_sha256': sha(TASK / 'artifact.json'),
        'artifact': artifact,
        'producer_head': artifact['head'],
        'functional_validation': functional,
        'functional_manifest_sha256': sha(functional_path),
        'prior_failed_unqualified': prior_failed(),
        'prior_complete_baseline': baseline,
        'baseline_provenance_correction': {'path': str(correction_path), 'sha256': sha(correction_path), 'data': correction,
            'published_path': 'scripts/rust/benchmarks/import-adoption-completion-provenance-correction.json',
            'published_sha256': sha(ROOT / 'scripts/rust/benchmarks/import-adoption-completion-provenance-correction.json')},
        'fixture_original_artifact': original_artifact,
        'fixture_reuse_note': 'Immutable real-Node baselines and prepared independent pinned-Node history oracle were created for original a800 artifact. They are reused unchanged for the native stack-owner-only source fix; no claim of regeneration with the new binary. Original validated pinned-Node builtin fact caches are preserved byte-for-byte under manifest fingerprints.',
        'binary_sha256': sha(artifact['artifact']),
        'controller_sha256': sha(__file__),
        'node_sha256': sha(NODE),
        'node_cli_sha256': sha(CLI),
        'node_wrapper_sha256': sha(WRAPPER),
        'helpers': {str(path.relative_to(ROOT)): sha(path) for path in sorted(path for path in (ROOT / 'scripts/rust').iterdir() if path.is_file() and path.suffix in ['.py', '.cjs', '.mjs', '.sh'])},
        'preparer_sha256': sha(TASK / 'prepare-fixtures.py'),
        'fixture_manifest_sha256': sha(preparation_path),
        'stage_manifests': {str(path): sha(path) for stage in STAGES.values()
                            for path in sorted(stage.glob('*.json'))
                            if path.name in ['fixtures.json', '.preparation-complete.json'] or 'oracle' in path.name},
        'supplemental_oracle_provenance': supplemental,
        'bitmap_history_oracle': {'path': str(STAGES['workspace-mutation'] / 'scope-bitmap-history-oracle.json'),
            'sha256': sha(STAGES['workspace-mutation'] / 'scope-bitmap-history-oracle.json'),
            'data': json.loads((STAGES['workspace-mutation'] / 'scope-bitmap-history-oracle.json').read_text())},
        'immutable_fixtures': actual_fixtures,
    }
    if inputs['native_source'] != artifact['native_source'] or inputs['binary_sha256'] != artifact['binary_sha256']:
        raise RuntimeError('artifact does not match frozen production source or release SHA')
    if inputs['source_tree'] != functional['tested_tree'] or inputs['native_source'] != functional['native_source']:
        raise RuntimeError('qualification source/tree differs from current functional validation')
    inputs['qualifier_head'] = inputs['head']
    return inputs


def jobs(binary, environment):
    base = ['--rust', binary, '--node-binary', str(NODE), '--node-cli', str(CLI), '--runs', '5']
    result = []
    for family, workloads in WORKLOADS.items():
        for workload in workloads:
            result.append((family, workload, ['python3', f'scripts/rust/bench-{family}.py', *base,
                                              '--stage', str(STAGES[family]), '--workload', workload], environment))
    regression_env = dict(environment, BIT_NODE_CLI=str(CLI), HOME='/var/tmp/transfer-final-fixtures/home',
                          BIT_GLOBALS_DIR='/var/tmp/transfer-final-fixtures/globals')
    for workload, fixture, command in [
        ('status', '/var/tmp/import-regression-fixtures/status', ['status', '--json']),
        ('checkout', '/var/tmp/import-regression-fixtures/checkout', ['checkout', '0.0.1', 'comp2', '--force-theirs', '-x']),
        ('export', '/var/tmp/transfer-final-fixtures/export-main', ['export']),
    ]:
        workload_env = regression_env.copy()
        if workload != 'export':
            workload_env.update(HOME='/var/tmp/import-regression-fixtures/home', USERPROFILE='/var/tmp/import-regression-fixtures/home', BIT_GLOBALS_DIR='/var/tmp/import-regression-fixtures/globals')
        result.append(('regressions', workload, ['python3', 'scripts/rust/bench-transfer.py', '--source', fixture,
            '--node', str(WRAPPER), '--rust', binary, '--remote', '/var/tmp/transfer-final-fixtures/transfer-remote',
            '--runs', '5', '--', *command], workload_env))
    assert len(result) == 30
    # Preserve the first valid outcome of the previously slower workload, even if slower again.
    result.sort(key=lambda job: (job[0], job[1]) != ('workspace-mutation', 'scope-rename-mixed'))
    return result


def ticks():
    raw = pathlib.Path('/proc/stat').read_text().splitlines()[0]
    values = list(map(int, raw.split()[1:9]))
    return sum(values), values[3] + values[4], raw


def sample(previous):
    current = ticks()
    total, idle = current[0] - previous[0], current[1] - previous[1]
    return current, {'monotonic': time.monotonic(), 'raw': current[2],
        'host_busy_percent': 100 * (total - idle) / total if total else 0}


def payload_files(prefix):
    return sorted(path for path in prefix.parent.glob(prefix.name + '.*') if path.is_file()) + sorted(
        path for path in prefix.with_suffix('.evidence').rglob('*') if path.is_file())


def checkpoint(evidence, identity, attempts):
    atomic(evidence / 'resume.json', {'identity': identity, 'attempts': attempts})


def resume(evidence, identity):
    path = evidence / 'resume.json'
    attempts = []
    if path.exists():
        record = json.loads(path.read_text())
        if record['identity'] != identity:
            raise RuntimeError('resume identity differs: source/artifact/helpers/controller/fixtures must be exact')
        attempts = record['attempts']
    referenced = set()
    seen = set()
    valid = set()
    for attempt in attempts:
        key = (attempt['family'], attempt['workload'])
        if key in valid or (key, attempt['attempt']) in seen:
            raise RuntimeError('duplicate or post-valid attempt in resume')
        expected_number = sum(1 for old_key, _ in seen if old_key == key) + 1
        if attempt['attempt'] != expected_number or not 1 <= expected_number <= 3:
            raise RuntimeError('noncontiguous attempt sequence')
        prefix = evidence / f'{key[0]}-{key[1]}-{expected_number}'
        if attempt['path'] != str(prefix.with_suffix('.monitor.json')):
            raise RuntimeError('monitor reference differs from attempt identity')
        if attempt['result_path'] not in [None, str(prefix.with_suffix('.result.json'))]:
            raise RuntimeError('result reference differs from attempt identity')
        if attempt['path'] and attempt['files'].get(str(pathlib.Path(attempt['path']).relative_to(evidence))) != attempt['sha256']:
            raise RuntimeError('monitor hash reference disagrees')
        seen.add((key, attempt['attempt']))
        for name, digest in attempt['files'].items():
            candidate = evidence / name
            if not candidate.resolve().is_relative_to(evidence.resolve()) or sha(candidate) != digest:
                raise RuntimeError('resume evidence missing, escaped or changed')
            referenced.add(name)
        if attempt['performance_valid']:
            valid.add(key)
    actual = {str(path.relative_to(evidence)) for path in evidence.rglob('*') if path.is_file()
              and path.name not in ['resume.json', 'summary.json']}
    if actual != referenced:
        raise RuntimeError(f'orphan/unreferenced attempt evidence: {sorted(actual ^ referenced)}')
    return attempts


def measure(job, number, evidence, verify):
    family, workload, argv, environment = job
    prefix = evidence / f'{family}-{workload}-{number}'
    if list(evidence.glob(prefix.name + '.*')):
        raise RuntimeError('attempt evidence already exists')
    result_path = prefix.with_suffix('.result.json')
    environment = environment.copy()
    if family == 'regressions':
        runtime = prefix.with_suffix('.evidence')
        runtime.mkdir()
        for key, name in [('HOME', 'home'), ('BIT_GLOBALS_DIR', 'globals')]:
            source = pathlib.Path(environment[key])
            destination = runtime / name
            shutil.copytree(source, destination, symlinks=True)
            environment[key] = str(destination)
        environment['USERPROFILE'] = environment['HOME']
    command = argv if family == 'regressions' else [*argv, '--output', str(result_path)]
    verify()
    gate, samples = [], []
    previous, consecutive, last_notice = ticks(), 0, time.monotonic()
    while consecutive < 40:
        time.sleep(.5)
        previous, row = sample(previous)
        gate.append(row)
        consecutive = consecutive + 1 if row['host_busy_percent'] < 30 else 0
        if time.monotonic() - last_notice >= 60:
            print(f'{family}/{workload}: waiting for 20 quiet seconds; current streak={consecutive / 2}s', flush=True)
            last_notice = time.monotonic()
    done = threading.Event()
    ready = threading.Event()
    monitor_initial = {}
    def monitor():
        previous = ticks()
        monitor_initial.update(monotonic=time.monotonic(), raw=previous[2])
        ready.set()
        while not done.wait(.5):
            previous, row = sample(previous)
            samples.append(row)
        _, row = sample(previous)
        samples.append(row)
    observer = threading.Thread(target=monitor)
    observer.start()
    ready.wait()
    try:
        with prefix.with_suffix('.stdout').open('w') as out, prefix.with_suffix('.stderr').open('w') as err:
            result = subprocess.run(command, cwd=ROOT, env=environment, stdout=out, stderr=err)
    finally:
        done.set()
        observer.join()
    verify()
    peak = max(row['host_busy_percent'] for row in samples)
    valid = result.returncode == 0 and peak < 80
    monitor_path = prefix.with_suffix('.monitor.json')
    atomic(monitor_path, {'command': command, 'start_gate': gate, 'monitor_initial': monitor_initial, 'samples': samples,
        'sample_interval_seconds': .5, 'host_busy_peak_percent': peak,
        'performance_valid': valid, 'exit_code': result.returncode,
        'isolated_environment': {key: environment.get(key) for key in ['HOME', 'USERPROFILE', 'BIT_GLOBALS_DIR', 'BIT_NODE_CLI', 'BIT_NODE_BINARY']}})
    if result.returncode == 0 and family == 'regressions':
        atomic(result_path, json.loads(prefix.with_suffix('.stdout').read_text()))
    if family != 'regressions':
        archive = prefix.with_suffix('.evidence')
        archive.mkdir()
        for path in (STAGES[family] / 'evidence').glob(workload + '-*'):
            if path.is_file():
                shutil.copy2(path, archive / path.name)
    files = {str(path.relative_to(evidence)): sha(path) for path in payload_files(prefix)}
    return {'family': family, 'workload': workload, 'attempt': number, 'path': str(monitor_path),
        'sha256': sha(monitor_path), 'performance_valid': valid, 'host_busy_peak_percent': peak,
        'exit_code': result.returncode, 'files': files, 'reproduce_argv': command,
        'result_path': str(result_path) if result_path.exists() else None}


def reports(identity, attempts, evidence):
    historical_path = 'scripts/rust/benchmarks/fork-planning-reuse-qualification.json'
    historical_bytes = subprocess.check_output(['git', 'show', 'HEAD:' + historical_path], cwd=ROOT)
    historical = json.loads(historical_bytes)
    archive = {'method': '30 independent complete workloads; 5 alternating pairs in timed/TTY/CI; '
        '20 consecutive seconds below30percent before launch; closed0.5second full-run peakbelow80percent; '
        'max3 attempts, retry host-invalid only; first valid slower result retained; no row deletion',
        'identity': identity, 'build_provenance': identity['artifact'],
        'producer_head': identity['producer_head'], 'qualifier_head': identity['qualifier_head'],
        'history_verification_method': 'Every surviving timed bitmap backup is validated against the prepared Node per-write preimage oracle at the last metadata write using that timestamp ID. Reasons/order, metadata prefix, modes and exact referenced file set remain checked. Overwritten logical transitions are oracle-derived only, not individually observable timed bytes. All raw collision-group proofs remain in workload evidence.',
        'prior_FAILED_unqualified': prior_archive(identity['prior_failed_unqualified']),
        'prior_complete_baseline': baseline_archive(identity['prior_complete_baseline']),
        'baseline_compiler_provenance_correction': identity['baseline_provenance_correction'],
        'controller_source': pathlib.Path(__file__).read_text(),
        'fixture_regeneration': {'source': (TASK / 'prepare-fixtures.py').read_text(),
            'sha256': identity['preparer_sha256'], 'manifest': json.loads((TASK / 'fixture-manifest.json').read_text()),
            'note': identity['fixture_reuse_note'] + ' Immutable paths remain hashed before/after every independent workload. Regression HOME/globals are copied per attempt and shared across existing helper internal trials.'},
        'historical_nonperformance_oracles': {'path': historical_path,
            'sha256': hashlib.sha256(historical_bytes).hexdigest(),
            'note': 'Historical parser/AST correctness evidence only; no historical timing qualifies this source.',
            **{key: historical[key] for key in ['empty_documentation_oracle', 'checkout_positional_parser_oracle'] if key in historical}},
        'attempts': []}
    selected = {}
    for attempt in attempts:
        entry = {'receipt': attempt, 'monitor': json.loads(pathlib.Path(attempt['path']).read_text())}
        if attempt['result_path']:
            value = json.loads(pathlib.Path(attempt['result_path']).read_text())
            entry['result'] = {'sha256': sha(attempt['result_path']), 'data': value}
            if attempt['performance_valid']:
                selected[(attempt['family'], attempt['workload'])] = (value, attempt)
        prefix = pathlib.Path(attempt['path'].removesuffix('.monitor.json'))
        observed = sorted(prefix.with_suffix('.evidence').glob('*.bitmap-history.json'))
        if (attempt['family'], attempt['workload']) == ('workspace-mutation', 'scope-rename-mixed'):
            if attempt['exit_code'] == 0 and len(observed) != 30:
                raise RuntimeError('complete scope workload must preserve 30 raw history proofs')
            entry['observed_bitmap_history_proofs'] = [
                {'path': str(path), 'sha256': sha(path), 'data': json.loads(path.read_text())}
                for path in observed]
        elif observed:
            raise RuntimeError('unexpected scope-only bitmap history proof files')
        archive['attempts'].append(entry)
    expected = {(family, name) for family, names in WORKLOADS.items() for name in names}
    expected.update(('regressions', name) for name in ['status', 'checkout', 'export'])
    if set(selected) != expected:
        raise RuntimeError('cannot publish incomplete qualification')
    expected_pairs = {(mode, number) for mode in ['timed', 'tty', 'ci'] for number in range(5)}
    for (family, workload), (value, _) in selected.items():
        actual_pairs = [(row['mode'], row['run'] if family == 'regressions' else row['pair']) for row in value['verified']]
        if len(actual_pairs) != 15 or set(actual_pairs) != expected_pairs:
            raise RuntimeError(f'incomplete or duplicate presentation pairs: {family}/{workload}')
    all_pairs = sum(len(value['verified']) for value, _ in selected.values())
    if all_pairs != 450:
        raise RuntimeError(f'expected450 pairs, got{all_pairs}')
    expected_native_pairs = sum(len(value['verified']) if family == 'regressions' else
        sum(row['native_ownership'] for row in value['verified'])
        for (family, _), (value, _) in selected.items())
    expected_modes = sum(len(value['median_ms']) if family == 'regressions' else
        sum(row['native_ownership'] for row in value['workloads'][name].values())
        for (family, name), (value, _) in selected.items())
    if expected_native_pairs != 440 or expected_modes != 88:
        raise RuntimeError(f'expected440 native pairs/88 modes, got{expected_native_pairs}/{expected_modes}')
    archive_path = ROOT / 'scripts/rust/benchmarks' / (REPORT_PREFIX + '-qualification.json')
    # No repository writes occur until every workload and frozen-input check has completed.
    atomic(archive_path, archive)
    slower, native_pairs, modes_count = [], 0, 0
    for family, suffix in [('import-adoption', ''), ('fork', '-fork'), ('identity', '-identity'),
                           ('add', '-add'), ('workspace-mutation', '-mutation'), ('regressions', '-regressions')]:
        rows = [(name, value, receipt) for (kind, name), (value, receipt) in selected.items() if kind == family]
        report = {'native_source': identity['native_source'], 'build_provenance': identity['artifact'],
            'measured_at_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(),
            'correctness_valid': True, 'performance_valid': True,
            'performance_qualification': 'Exact-source first host-valid complete workloads; slower results remain valid and listed.',
            'workload_reports': {name: value for name, value, _ in rows},
            'host_monitor': {name: receipt for name, _, receipt in rows},
            'qualification_evidence': {'path': str(archive_path.relative_to(ROOT)), 'sha256': sha(archive_path)}}
        for name, value, _ in rows:
            native_pairs += len(value['verified']) if family == 'regressions' else sum(row['native_ownership'] for row in value['verified'])
            modes = value['median_ms'] if family == 'regressions' else value['workloads'][name]
            for mode, row in modes.items():
                if family != 'regressions' and not row['native_ownership']:
                    continue
                modes_count += 1
                median = row if family == 'regressions' else row['median_ms']
                if median['rust'] >= median['node']:
                    slower.append({'family': family, 'workload': name, 'mode': mode, 'median_ms': median})
        atomic(ROOT / 'scripts/rust/benchmarks' / (REPORT_PREFIX + suffix + '.json'), report)
    summary = {'pairs': all_pairs, 'native_pairs': native_pairs, 'eligible_modes': modes_count, 'slower': slower}
    atomic(evidence / 'summary.json', summary)
    print(json.dumps(summary), flush=True)


def main():
    artifact = json.loads((TASK / 'artifact.json').read_text())
    common = load_common()
    identity = frozen_inputs(common, artifact)
    evidence = TASK / 'qualification' / (identity['qualifier_head'] + '-' + identity['controller_sha256'][:12])
    evidence.mkdir(parents=True, exist_ok=True)
    attempts = resume(evidence, identity)
    environment = os.environ.copy()
    environment.update(TMPDIR='/var/tmp', BIT_NODE_BINARY=str(NODE), PATH=str(NODE.parent) + ':' + environment['PATH'])
    for key in ['CI', 'NO_COLOR', 'FORCE_COLOR', 'BIT_NATIVE', 'BIT_NATIVE_TRACE', 'NODE_OPTIONS']:
        environment.pop(key, None)
    def verify():
        if frozen_inputs(common, artifact) != identity:
            raise RuntimeError('frozen source/binary/helper/fixture identity changed')
    checkpoint(evidence, identity, attempts)
    for job in jobs(artifact['artifact'], environment):
        key = job[:2]
        prior = [row for row in attempts if (row['family'], row['workload']) == key]
        if prior and prior[-1]['performance_valid']:
            print(f'{key}: retained first valid result without remeasurement', flush=True)
            continue
        if prior and prior[-1]['exit_code']:
            raise RuntimeError('prior correctness failure; no retry permitted')
        for number in range(len(prior) + 1, 4):
            receipt = measure(job, number, evidence, verify)
            attempts.append(receipt)
            checkpoint(evidence, identity, attempts)
            print(f'{key}/{number}: exit={receipt["exit_code"]} peak={receipt["host_busy_peak_percent"]} valid={receipt["performance_valid"]}', flush=True)
            if receipt['exit_code']:
                raise RuntimeError('parity/command failure; no automatic retry')
            if receipt['performance_valid']:
                break
        else:
            raise RuntimeError(f'{key}: max3 whole-workload host-invalid attempts')
    verify()
    reports(identity, attempts, evidence)


if __name__ == '__main__':
    main()

