    seen = set()
    valid = set()
    for attempt in attempts:
        key = (attempt['family'], attempt['workload'])
        if key in valid or (key, attempt['attempt']) in seen:
            raise RuntimeError('duplicate or post-valid attempt in resume')
        expected_number = sum(1 for old_key, _ in seen if old_key == key) + 1
        if attempt['attempt'] != expected_number or not 1 <= expected_number <= 3:
            raise RuntimeError('noncontiguous attempt sequence')
        prefix = evidence / f'{key[0]}-{key[1]}-{expected_number}'
        if attempt['path'] != str(prefix.with_suffix('.monitor.json')):
            raise RuntimeError('monitor reference differs from attempt identity')
        if attempt['result_path'] not in [None, str(prefix.with_suffix('.result.json'))]:
            raise RuntimeError('result reference differs from attempt identity')
        if attempt['path'] and attempt['files'].get(str(pathlib.Path(attempt['path']).relative_to(evidence))) != attempt['sha256']:
            raise RuntimeError('monitor hash reference disagrees')
        seen.add((key, attempt['attempt']))
        for name, digest in attempt['files'].items():
            candidate = evidence / name
            if not candidate.resolve().is_relative_to(evidence.resolve()) or sha(candidate) != digest:
                raise RuntimeError('resume evidence missing, escaped or changed')
            referenced.add(name)
        if attempt['performance_valid']:
            valid.add(key)
    actual = {str(path.relative_to(evidence)) for path in evidence.rglob('*') if path.is_file()
              and path.name not in ['resume.json', 'summary.json']}
    if actual != referenced:
        raise RuntimeError(f'orphan/unreferenced attempt evidence: {sorted(actual ^ referenced)}')
    return attempts


def measure(job, number, evidence, verify):
    family, workload, argv, environment = job
    prefix = evidence / f'{family}-{workload}-{number}'
    if list(evidence.glob(prefix.name + '.*')):
        raise RuntimeError('attempt evidence already exists')
    result_path = prefix.with_suffix('.result.json')
    environment = environment.copy()
    if family == 'regressions':
        runtime = prefix.with_suffix('.evidence')
        runtime.mkdir()
        for key, name in [('HOME', 'home'), ('BIT_GLOBALS_DIR', 'globals')]:
            source = pathlib.Path(environment[key])
            destination = runtime / name
            shutil.copytree(source, destination, symlinks=True)
            environment[key] = str(destination)
        environment['USERPROFILE'] = environment['HOME']
    command = argv if family == 'regressions' else [*argv, '--output', str(result_path)]
    verify()
    gate, samples = [], []
    previous, consecutive, last_notice = ticks(), 0, time.monotonic()
    while consecutive < 40:
        time.sleep(.5)
        previous, row = sample(previous)
        gate.append(row)
        consecutive = consecutive + 1 if row['host_busy_percent'] < 30 else 0
        if time.monotonic() - last_notice >= 60:
            print(f'{family}/{workload}: waiting for 20 quiet seconds; current streak={consecutive / 2}s', flush=True)
            last_notice = time.monotonic()
    done = threading.Event()
    ready = threading.Event()
    monitor_initial = {}
    def monitor():
        previous = ticks()
        monitor_initial.update(monotonic=time.monotonic(), raw=previous[2])
        ready.set()
        while not done.wait(.5):
            previous, row = sample(previous)
            samples.append(row)
        _, row = sample(previous)
        samples.append(row)
    observer = threading.Thread(target=monitor)
    observer.start()
    ready.wait()
    try:
        with prefix.with_suffix('.stdout').open('w') as out, prefix.with_suffix('.stderr').open('w') as err:
            result = subprocess.run(command, cwd=ROOT, env=environment, stdout=out, stderr=err)
    finally:
        done.set()
        observer.join()
    verify()
    peak = max(row['host_busy_percent'] for row in samples)
    valid = result.returncode == 0 and peak < 80
    monitor_path = prefix.with_suffix('.monitor.json')
    atomic(monitor_path, {'command': command, 'start_gate': gate, 'monitor_initial': monitor_initial, 'samples': samples,
        'sample_interval_seconds': .5, 'host_busy_peak_percent': peak,
        'performance_valid': valid, 'exit_code': result.returncode,
        'isolated_environment': {key: environment.get(key) for key in ['HOME', 'USERPROFILE', 'BIT_GLOBALS_DIR', 'BIT_NODE_CLI', 'BIT_NODE_BINARY']}})
    if result.returncode == 0 and family == 'regressions':
        atomic(result_path, json.loads(prefix.with_suffix('.stdout').read_text()))
    if family != 'regressions':
        archive = prefix.with_suffix('.evidence')
        archive.mkdir()
        for path in (STAGES[family] / 'evidence').glob(workload + '-*'):
            if path.is_file():
                shutil.copy2(path, archive / path.name)
    files = {str(path.relative_to(evidence)): sha(path) for path in payload_files(prefix)}
    return {'family': family, 'workload': workload, 'attempt': number, 'path': str(monitor_path),
        'sha256': sha(monitor_path), 'performance_valid': valid, 'host_busy_peak_percent': peak,
        'exit_code': result.returncode, 'files': files, 'reproduce_argv': command,
        'result_path': str(result_path) if result_path.exists() else None}


def reports(identity, attempts, evidence):
    historical_path = 'scripts/rust/benchmarks/fork-planning-reuse-qualification.json'
    historical_bytes = subprocess.check_output(['git', 'show', 'HEAD:' + historical_path], cwd=ROOT)
    historical = json.loads(historical_bytes)
    archive = {'method': '30 independent complete workloads; 5 alternating pairs in timed/TTY/CI; '
        '20 consecutive seconds below30percent before launch; closed0.5second full-run peakbelow80percent; '
        'max3 attempts, retry host-invalid only; first valid slower result retained; no row deletion',
        'identity': identity, 'build_provenance': identity['artifact'],
        'producer_head': identity['producer_head'], 'qualifier_head': identity['qualifier_head'],
        'history_verification_method': 'Every surviving timed bitmap backup is validated against the prepared Node per-write preimage oracle at the last metadata write using that timestamp ID. Reasons/order, metadata prefix, modes and exact referenced file set remain checked. Overwritten logical transitions are oracle-derived only, not individually observable timed bytes. All raw collision-group proofs remain in workload evidence.',
        'prior_FAILED_unqualified': prior_archive(identity['prior_failed_unqualified']),
        'prior_complete_baseline': baseline_archive(identity['prior_complete_baseline']),
        'baseline_compiler_provenance_correction': identity['baseline_provenance_correction'],
        'controller_source': pathlib.Path(__file__).read_text(),
        'fixture_regeneration': {'source': (TASK / 'prepare-fixtures.py').read_text(),
            'sha256': identity['preparer_sha256'], 'manifest': json.loads((TASK / 'fixture-manifest.json').read_text()),
            'note': identity['fixture_reuse_note'] + ' Immutable paths remain hashed before/after every independent workload. Regression HOME/globals are copied per attempt and shared across existing helper internal trials.'},
        'historical_nonperformance_oracles': {'path': historical_path,
            'sha256': hashlib.sha256(historical_bytes).hexdigest(),
            'note': 'Historical parser/AST correctness evidence only; no historical timing qualifies this source.',
            **{key: historical[key] for key in ['empty_documentation_oracle', 'checkout_positional_parser_oracle'] if key in historical}},
        'attempts': []}
    selected = {}
    for attempt in attempts:
        entry = {'receipt': attempt, 'monitor': json.loads(pathlib.Path(attempt['path']).read_text())}
        if attempt['result_path']:
            value = json.loads(pathlib.Path(attempt['result_path']).read_text())
            entry['result'] = {'sha256': sha(attempt['result_path']), 'data': value}
            if attempt['performance_valid']:
                selected[(attempt['family'], attempt['workload'])] = (value, attempt)
        prefix = pathlib.Path(attempt['path'].removesuffix('.monitor.json'))
        observed = sorted(prefix.with_suffix('.evidence').glob('*.bitmap-history.json'))
        if (attempt['family'], attempt['workload']) == ('workspace-mutation', 'scope-rename-mixed'):
            if attempt['exit_code'] == 0 and len(observed) != 30:
                raise RuntimeError('complete scope workload must preserve 30 raw history proofs')
            entry['observed_bitmap_history_proofs'] = [
                {'path': str(path), 'sha256': sha(path), 'data': json.loads(path.read_text())}
                for path in observed]
        elif observed:
            raise RuntimeError('unexpected scope-only bitmap history proof files')
        archive['attempts'].append(entry)
    expected = {(family, name) for family, names in WORKLOADS.items() for name in names}
    expected.update(('regressions', name) for name in ['status', 'checkout', 'export'])
    if set(selected) != expected:
        raise RuntimeError('cannot publish incomplete qualification')
    expected_pairs = {(mode, number) for mode in ['timed', 'tty', 'ci'] for number in range(5)}
    for (family, workload), (value, _) in selected.items():
        actual_pairs = [(row['mode'], row['run'] if family == 'regressions' else row['pair']) for row in value['verified']]
        if len(actual_pairs) != 15 or set(actual_pairs) != expected_pairs:
            raise RuntimeError(f'incomplete or duplicate presentation pairs: {family}/{workload}')
    all_pairs = sum(len(value['verified']) for value, _ in selected.values())
    if all_pairs != 450:
        raise RuntimeError(f'expected450 pairs, got{all_pairs}')
    expected_native_pairs = sum(len(value['verified']) if family == 'regressions' else
        sum(row['native_ownership'] for row in value['verified'])
        for (family, _), (value, _) in selected.items())
    expected_modes = sum(len(value['median_ms']) if family == 'regressions' else
        sum(row['native_ownership'] for row in value['workloads'][name].values())
        for (family, name), (value, _) in selected.items())
    if expected_native_pairs != 440 or expected_modes != 88:
        raise RuntimeError(f'expected440 native pairs/88 modes, got{expected_native_pairs}/{expected_modes}')
    archive_path = ROOT / 'scripts/rust/benchmarks' / (REPORT_PREFIX + '-qualification.json')
    # No repository writes occur until every workload and frozen-input check has completed.
    atomic(archive_path, archive)
    slower, native_pairs, modes_count = [], 0, 0
    for family, suffix in [('import-adoption', ''), ('fork', '-fork'), ('identity', '-identity'),
                           ('add', '-add'), ('workspace-mutation', '-mutation'), ('regressions', '-regressions')]:
        rows = [(name, value, receipt) for (kind, name), (value, receipt) in selected.items() if kind == family]
        report = {'native_source': identity['native_source'], 'build_provenance': identity['artifact'],
            'measured_at_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(),
            'correctness_valid': True, 'performance_valid': True,
            'performance_qualification': 'Exact-source first host-valid complete workloads; slower results remain valid and listed.',
            'workload_reports': {name: value for name, value, _ in rows},
            'host_monitor': {name: receipt for name, _, receipt in rows},
            'qualification_evidence': {'path': str(archive_path.relative_to(ROOT)), 'sha256': sha(archive_path)}}
        for name, value, _ in rows:
            native_pairs += len(value['verified']) if family == 'regressions' else sum(row['native_ownership'] for row in value['verified'])
            modes = value['median_ms'] if family == 'regressions' else value['workloads'][name]
            for mode, row in modes.items():
                if family != 'regressions' and not row['native_ownership']:
                    continue
                modes_count += 1
                median = row if family == 'regressions' else row['median_ms']
                if median['rust'] >= median['node']:
                    slower.append({'family': family, 'workload': name, 'mode': mode, 'median_ms': median})
        atomic(ROOT / 'scripts/rust/benchmarks' / (REPORT_PREFIX + suffix + '.json'), report)
    summary = {'pairs': all_pairs, 'native_pairs': native_pairs, 'eligible_modes': modes_count, 'slower': slower}
    atomic(evidence / 'summary.json', summary)
    print(json.dumps(summary), flush=True)


def main():
    artifact = json.loads((TASK / 'artifact.json').read_text())
    common = load_common()
    identity = frozen_inputs(common, artifact)
    evidence = TASK / 'qualification' / (identity['qualifier_head'] + '-' + identity['controller_sha256'][:12])
    evidence.mkdir(parents=True, exist_ok=True)
    attempts = resume(evidence, identity)
    environment = os.environ.copy()
    environment.update(TMPDIR='/var/tmp', BIT_NODE_BINARY=str(NODE), PATH=str(NODE.parent) + ':' + environment['PATH'])
    for key in ['CI', 'NO_COLOR', 'FORCE_COLOR', 'BIT_NATIVE', 'BIT_NATIVE_TRACE', 'NODE_OPTIONS']:
        environment.pop(key, None)
    def verify():
        if frozen_inputs(common, artifact) != identity:
            raise RuntimeError('frozen source/binary/helper/fixture identity changed')
    checkpoint(evidence, identity, attempts)
    for job in jobs(artifact['artifact'], environment):
        key = job[:2]
        prior = [row for row in attempts if (row['family'], row['workload']) == key]
        if prior and prior[-1]['performance_valid']:
            print(f'{key}: retained first valid result without remeasurement', flush=True)
            continue
        if prior and prior[-1]['exit_code']:
            raise RuntimeError('prior correctness failure; no retry permitted')
        for number in range(len(prior) + 1, 4):
            receipt = measure(job, number, evidence, verify)
            attempts.append(receipt)
            checkpoint(evidence, identity, attempts)
            print(f'{key}/{number}: exit={receipt["exit_code"]} peak={receipt["host_busy_peak_percent"]} valid={receipt["performance_valid"]}', flush=True)
            if receipt['exit_code']:
                raise RuntimeError('parity/command failure; no automatic retry')
            if receipt['performance_valid']:
                break
        else:
            raise RuntimeError(f'{key}: max3 whole-workload host-invalid attempts')
    verify()
    reports(identity, attempts, evidence)


if __name__ == '__main__':
    main()

